"""Package and technically verify the actual new staging review; never accept it."""
from pathlib import Path
import hashlib,json,subprocess,sys
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'artifacts/staging-v003';WORK=ROOT.parents[3]
sys.path.insert(0,str(WORK/'experiments/001_heavy_box'))
from journal import append_event
def run(args):return subprocess.run(args,check=True,capture_output=True,text=True)
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
output=OUT/'action-review-v003.mp4';assert not output.exists() or '--resume' in sys.argv
if not output.exists():run(['ffmpeg','-hide_banner','-loglevel','error','-i',str(OUT/'action-review-v002.mp4'),'-i',str(OUT/'action-red-v003.mp4'),'-filter_complex','[1:v]setpts=PTS-STARTPTS[a];[0:v]trim=start_frame=72:end_frame=672,setpts=PTS-STARTPTS[b];[a][b]concat=n=2:v=1:a=0[v]','-map','[v]','-map','0:a:0','-c:v','libx264','-preset','medium','-crf','18','-pix_fmt','yuv420p','-r','24','-c:a','copy','-movflags','+faststart',str(output)])
probe=json.loads(run(['ffprobe','-v','error','-count_frames','-show_entries','stream=index,codec_type,codec_name,width,height,r_frame_rate,nb_read_frames,sample_rate,channels,duration','-of','json',str(output)]).stdout)
v,a=probe['streams'];assert v['codec_type']=='video' and v['nb_read_frames']=='672' and v['r_frame_rate']=='24/1' and v['width']==1280 and v['height']==720
assert a['channels']==2 and a['sample_rate']=='48000' and float(a['duration'])==28
run(['ffmpeg','-v','error','-i',str(output),'-f','null','-'])
measurement=run(['ffmpeg','-hide_banner','-i',str(output),'-vn','-af','loudnorm=I=-18:TP=-2:LRA=11:print_format=json','-f','null','-']).stderr
levels,_=json.JSONDecoder().raw_decode(measurement[measurement.rfind('{'):]);assert float(levels['input_tp'])<0
checks={'artifact':output.name,'sha256':sha(output),'decode':'complete; no errors','streams':probe['streams'],'audio_measurement':levels,'audio_finishing':'Shared premaster plus 4 dB, cached as review-foley.wav; AAC stream preserved during framing correction.','native_project':'action-staging-v004.blend','native_sha256':sha(OUT/'action-staging-v004.blend'),'subjective_review':'Staging, new Foley audition and normal-speed motion acceptance pending user. Agent has not heard audio.','full_film_duration_seconds':150,'review_excerpt_seconds':28}
(OUT/'encoded-checks.json').write_text(json.dumps(checks,indent=2)+'\n')
h=OUT/'review.html';h.write_text(h.read_text().replace('action-review-v002.mp4','action-review-v003.mp4').replace('action-staging-v003.blend','action-staging-v004.blend'))
