plan['staging_excerpts']={'review':'artifacts/staging-v003/action-review-v003.mp4','duration_seconds':28,'shots':['S02a','S02b','S08','S10'],'events_source':'artifacts/staging-v003/native-checks.json','timing_scope':'Compressed representative excerpts; does not replace the selected 150-second shot timing.','foley_candidates':'artifacts/staging-v003/audio-plan.json','voices':'Dialogue captions only in this staging selection; actual cast performances remain pending.'}
(ROOT/'production.json').write_text(json.dumps(plan,indent=2)+'\n')
provenance={'kind':'Original generated animation heads; prepared by native UV cropping; original raster pixels retained','files':{fn:sha(ROOT/'assets/art-v003'/fn) for fn in ['bruno-foden-oliver-carrick.png','donnarumma-mbeumo.png','drawing-bounds.json']},'generation_prompts':['cast-generation-prompt.txt','save-initial-prompt.txt','save-correction-prompt.txt'],'source_art':['assets/art-v002/head-expressions.png'],'likeness_references':['artifacts/staging-v003/carrick-reference.webp','artifacts/staging-v003/donnarumma-reference.jpg','research/visual-references/official-highlights-picture.mp4'],'rejected_generation':'exec-7d06cf6b-a435-4930-9b34-25f131469ea7.png — Donnarumma likeness too close to Bruno; not used in scene','selected_generated_files':['exec-99bc8bbf-8032-4b6e-bd3c-6cdc409dcf86.png','exec-ca02484f-5f0d-4c57-923c-c9c5b09901a4.png'],'review_limits':'New action cast pending user staging acceptance; no final all-angle character approval.'}
(ROOT/'assets/art-v003/provenance.json').write_text(json.dumps(provenance,indent=2)+'\n')
inputs=['storyline-v001.md','assets/style-selection.json','assets/art-v003/bruno-foden-oliver-carrick.png','assets/art-v003/donnarumma-mbeumo.png','assets/art-v003/drawing-bounds.json']
outputs=['artifacts/staging-v003/'+p for p in ['action-review-v003.mp4','action-staging-v004.blend','native-checks.json','encoded-checks.json','review.html','review.md']]
append_event(ROOT,stage='S02-S08-S10/action-staging',status='completed',reviewer='assistant',intent='Carry accepted construction into the film’s hardest contacts and ending.',method='Visible native authoring; 18 new head drawings; original helper reused with driven handles; 672-frame attachment checks, selected-frame inspection and encoded decode/measurement.',result='28-second representative review ready. Revised grounded kick, glove capture/landing, crying fountain, attached fishing prop/line, readable captions and complete callback. S01 accepted artifacts and B sound source retained. Technical checks passed; no agent listening or user approval of new work claimed.',decision='Present new action staging and new Foley candidates together.',inputs=inputs,outputs=outputs)
append_event(ROOT,stage='checkpoint/staging-v003/staging',status='pending_review',intent='Review new football actions and the ending before expanding detailed animation.',method='28-second native staging movie, cast/role map and source/reference comparison.',result='Review question: Do the red-card action, keeper save and crying-to-fishing ending read clearly and feel right in this treatment?',decision='Await user feedback on newly presented staging only; retain S01 approval.',inputs=inputs,outputs=outputs)
append_event(ROOT,stage='checkpoint/staging-v003/sound',status='pending_review',intent='Audition new sparse foreground effects without reopening B.',method='Play the same cached Foley mix in the staging movie and isolated audio control.',result='New whistle, impact, catch, graphic pop, water/float and squeak candidates are auditionable. Dialogue is captioned; final voices not represented. Agent has not heard audio.',decision='Do not carry unaccepted new effects or claim final cast performance.',inputs=['artifacts/staging-v003/audio-plan.json',*['assets/audio-v002/'+p.name for p in sorted((ROOT/'assets/audio-v002').glob('*.wav'))]],outputs=['artifacts/staging-v003/action-review-v003.mp4','artifacts/staging-v003/review-foley.wav'])
parent=ROOT.parents[1]/'README.md';txt=parent.read_text();lines=txt.splitlines();lines=[('**Status, 15 September:** the 150-second first film is in production. The user selected sound B and approved the revised S01 head/neck construction and connected motion. New representative red-card, late-save and ending staging is ready for review. The complete combined animatic and final voices remain pending; see the video journal for exact accepted artifacts.') if l.startswith('**Status, 15 September:**') else l for l in lines];parent.write_text('\n'.join(lines)+'\n')
print(json.dumps({'review':str(output),'frames':672,'seconds':28,'true_peak_dbfs':levels['input_tp'],'status':'pending user staging/sound review'}))
